    { const char * tb_v971 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v971; }
    { const char * tb_v972 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v972; }
    { const char * tb_v973 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v973; }
    { const char * tb_v974 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v974; }
    { const char * tb_v975 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v975; }
    { const char * tb_v976 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v976; }
    { const char * tb_v977 = "static _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v977; }
    { const char * tb_v978 = "static _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v978; }
    { const char * tb_v979 = "static int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v979; }
    { const char * tb_v980 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v980; }
    { const char * tb_v981 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v981; }
    { const char * tb_v982 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v982; }
    { const char * tb_v983 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v983; }
    { const char * tb_v984 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v984; }
    { const char * tb_v985 = "static void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
    { const char * tb_v986 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v986; }
    { const char * tb_v987 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v987; }
    { const char * tb_v988 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v988; }
    { const char * tb_v989 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v989; }
    { const char * tb_v990 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v990; }
