    { const char * tb_v993 = "            tb_chunks = realloc(tb_chunks, sizeof(tb_chunk) * tb_capchunks);\n"; *(const char * *)tb_grow(v_lines) = tb_v993; }
    { const char * tb_v994 = "            if (tb_chunks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v994; }
    { const char * tb_v995 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v995; }
    { const char * tb_v996 = "        char *mem = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v996; }
    { const char * tb_v997 = "        if (mem == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v997; }
    { const char * tb_v998 = "        tb_chunks[tb_nchunks] = (tb_chunk){mem, size, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v998; }
    { const char * tb_v999 = "        c = &tb_chunks[tb_nchunks];\n"; *(const char * *)tb_grow(v_lines) = tb_v999; }
