    { const char * tb_v1001 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1001; }
    { const char * tb_v1002 = "    void *p = c->mem + c->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v1002; }
