    { const char * tb_v1018 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1018; }
    { const char * tb_v1019 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1019; }
    { const char * tb_v1020 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v1020; }
    { const char * tb_v1021 = "static int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1021; }
    { const char * tb_v1022 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1022; }
    { const char * tb_v1023 = "    tb_mark t = tb_marks[tb_temp_depth - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1023; }
    { const char * tb_v1024 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1024; }
    { const char * tb_v1025 = "        const char *m = tb_chunks[i].mem;\n"; *(const char * *)tb_grow(v_lines) = tb_v1025; }
    { const char * tb_v1026 = "        if ((const char *)p >= m && (const char *)p < m + tb_chunks[i].size)\n"; *(const char * *)tb_grow(v_lines) = tb_v1026; }
    { const char * tb_v1027 = "            return i > t.n - 1 || (i == t.n - 1 && (const char *)p - m >= t.used);\n"; *(const char * *)tb_grow(v_lines) = tb_v1027; }
    { const char * tb_v1028 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1028; }
    { const char * tb_v1029 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1029; }
    { const char * tb_v1030 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1030; }
    { const char * tb_v1031 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v1031; }
    { const char * tb_v1032 = "static _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v1032; }
    { const char * tb_v1033 = "static _Thread_local long long tb_lc_n[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v1033; }
    { const char * tb_v1034 = "static _Thread_local int tb_lc_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v1034; }
    { const char * tb_v1035 = "static inline void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1035; }
    { const char * tb_v1036 = "static inline void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1036; }
    { const char * tb_v1037 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1037; }
    { const char * tb_v1038 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1038; }
