    { const char * tb_v1044 = "    tb_temp_depth -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1044; }
    { const char * tb_v1045 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v1045; }
    { const char * tb_v1046 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1046; }
    { const char * tb_v1047 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1047; }
    { const char * tb_v1048 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v1048; }
    { const char * tb_v1049 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1049; }
    { const char * tb_v1050 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v1050; }
    { const char * tb_v1051 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v1051; }
    { const char * tb_v1052 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v1052; }
    { const char * tb_v1053 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v1053; }
    { const char * tb_v1054 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v1054; }
    { const char * tb_v1055 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v1055; }
    { const char * tb_v1056 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v1056; }
    { const char * tb_v1057 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1057; }
    { const char * tb_v1058 = "static void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1058; }
    { const char * tb_v1059 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1059; }
    { const char * tb_v1060 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1060; }
    { const char * tb_v1061 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1061; }
    { const char * tb_v1062 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1062; }
    { const char * tb_v1063 = "static void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1063; }
    { const char * tb_v1064 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1064; }
