    { const char * tb_v2214 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2214; }
    { const char * tb_v2215 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2215; }
