    { const char * tb_v2230 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2230; }
    { const char * tb_v2231 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2231; }
