    { const char * tb_v2240 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2240; }
    { const char * tb_v2241 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2241; }
    { const char * tb_v2242 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2242; }
    { const char * tb_v2243 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v2243; }
