    { const char * tb_v2253 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v2253; }
    { const char * tb_v2254 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2254; }
    { const char * tb_v2255 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2255; }
