    { const char * tb_v2258 = "    memset(d->slots, 0, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2258; }
    { const char * tb_v2259 = "    unsigned long long mask = nslots - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2259; }
    { const char * tb_v2260 = "    for (long long at = 0; at < d->keys->len; at++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2260; }
    { const char * tb_v2261 = "        unsigned long long i = tb_hash(d, d->keys->data + at * d->keys->size) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2261; }
    { const char * tb_v2262 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2262; }
    { const char * tb_v2263 = "        d->slots[i] = at + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2263; }
    { const char * tb_v2264 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2264; }
    { const char * tb_v2265 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2265; }
    { const char * tb_v2266 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v2266; }
    { const char * tb_v2267 = "static void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2267; }
    { const char * tb_v2268 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2268; }
    { const char * tb_v2269 = "    while (n < d->keys->len * 2 + 2) n *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2269; }
