    { const char * tb_v2280 = "    d->npos = npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v2280; }
    { const char * tb_v2281 = "    d->mode = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2281; }
    { const char * tb_v2282 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2282; }
