    { const char * tb_v2293 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v2293; }
    { const char * tb_v2294 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v2294; }
    { const char * tb_v2295 = "static void tb_lclear(tb_list *l, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2295; }
    { const char * tb_v2296 = "    if (l->cap < 0) tb_crash(line, \".clear() нельзя, пока по списку идёт each ... by N\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2296; }
    { const char * tb_v2297 = "    int temp = tb_nchunks > 0 && tb_in_temp(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v2297; }
    { const char * tb_v2298 = "    if (!temp) tb_gc_free(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v2298; }
    { const char * tb_v2299 = "    long long cap = l->size == 0 ? 64 : 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2299; }
    { const char * tb_v2300 = "    long long bytes = l->size == 0 ? 8 : l->size * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2300; }
