    { const char * tb_v2302 = "    if (l->data == 0) tb_crash(line, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2302; }
    { const char * tb_v2303 = "    memset(l->data, 0, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2303; }
    { const char * tb_v2304 = "    l->len = 0; l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2304; }
    { const char * tb_v2305 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2305; }
    { const char * tb_v2306 = "static void tb_dclear(tb_dict *d, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2306; }
    { const char * tb_v2307 = "    tb_lclear(d->keys, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v2307; }
