    { const char * tb_v2314 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2314; }
    { const char * tb_v2315 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v2315; }
    { const char * tb_v2316 = "static void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2316; }
    { const char * tb_v2317 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v2317; }
    { const char * tb_v2318 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2318; }
    { const char * tb_v2319 = "        if (n == 1) { d->base = k; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2319; }
