    { const char * tb_v2482 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2482; }
    { const char * tb_v2483 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2483; }
    { const char * tb_v2484 = "static pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2484; }
    { const char * tb_v2485 = "static pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2485; }
    { const char * tb_v2486 = "static int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2486; }
    { const char * tb_v2487 = "static volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2487; }
