    { const char * tb_v2491 = "static void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2491; }
    { const char * tb_v2492 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2492; }
    { const char * tb_v2493 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v2493; }
    { const char * tb_v2494 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2494; }
    { const char * tb_v2495 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2495; }
    { const char * tb_v2496 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2496; }
    { const char * tb_v2497 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v2497; }
    { const char * tb_v2498 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2498; }
    { const char * tb_v2499 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2499; }
    { const char * tb_v2500 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2500; }
    { const char * tb_v2501 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2501; }
    { const char * tb_v2502 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v2502; }
    { const char * tb_v2503 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v2503; }
    { const char * tb_v2504 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v2504; }
    { const char * tb_v2505 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v2505; }
    { const char * tb_v2506 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2506; }
    { const char * tb_v2507 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2507; }
    { const char * tb_v2508 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2508; }
    { const char * tb_v2509 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2509; }
    { const char * tb_v2510 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2510; }
