    { const char * tb_v2512 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v2512; }
    { const char * tb_v2513 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2513; }
    { const char * tb_v2514 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2514; }
    { const char * tb_v2515 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2515; }
    { const char * tb_v2516 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2516; }
    { const char * tb_v2517 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2517; }
    { const char * tb_v2518 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2518; }
    { const char * tb_v2519 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2519; }
    { const char * tb_v2520 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2520; }
    { const char * tb_v2521 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2521; }
