    { const char * tb_v2523 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v2523; }
    { const char * tb_v2524 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2524; }
    { const char * tb_v2525 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2525; }
    { const char * tb_v2526 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2526; }
    { const char * tb_v2527 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2527; }
    { const char * tb_v2528 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2528; }
    { const char * tb_v2529 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2529; }
    { const char * tb_v2530 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2530; }
    { const char * tb_v2531 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2531; }
    { const char * tb_v2532 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2532; }
    { const char * tb_v2533 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v2533; }
    { const char * tb_v2534 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2534; }
    { const char * tb_v2535 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v2535; }
    { const char * tb_v2536 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2536; }
    { const char * tb_v2537 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2537; }
    { const char * tb_v2538 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2538; }
    { const char * tb_v2539 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2539; }
    { const char * tb_v2540 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2540; }
